ice","name":"Homeowner Claim Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/home-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Claim Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/commercial-hoa-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof Damage Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind Damage Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/santa-ana-wind-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Atmospheric River & Storm Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/atmospheric-river-storm-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Leak Claim Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/water-leak-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire, Smoke & Ash Claim Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/smoke-ash-fire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Total Loss Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/wildfire-total-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Contents & Personal Property Appraisal","url":"https://californiainsuranceappraiser.com/disputed-claim-services/contents-inventory-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://californiainsuranceappraiser.com/disputed-claim-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://californiainsuranceappraiser.com/disputed-claim-services/umpire-appointment-services/"}}]},"knowsAbout":["Insurance appraisal","California Insurance Code §2071","Wildfire claims","Smoke damage","Xactimate estimating","Umpire services"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://californiainsuranceappraiser.com/#website","url":"https://californiainsuranceappraiser.com/","name":"California Insurance Appraiser","publisher":{"@id":"https://californiainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#webpage","url":"https://californiainsuranceappraiser.com/claim-terms-defined/","name":"Insurance Claim Terms Defined | Glossary of 40+ Terms","description":"Insurance claim terms defined in plain English: ACV, holdback, FAIR Plan, DIC, extended replacement cost, umpire and more, searchable.","inLanguage":"en-US","isPartOf":{"@id":"https://californiainsuranceappraiser.com/#website"},"about":{"@id":"https://californiainsuranceappraiser.com/#business"},"publisher":{"@id":"https://californiainsuranceappraiser.com/#business"},"dateModified":"2026-11-16","breadcrumb":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#breadcrumb"},"primaryImageOfPage":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#primaryimage"},"image":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#primaryimage"},"mainEntity":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"ImageObject","@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#primaryimage","url":"https://californiainsuranceappraiser.com/assets/img/photos/paper-writing.webp","contentUrl":"https://californiainsuranceappraiser.com/assets/img/photos/paper-writing.webp","width":960,"height":640,"caption":"Person writing notes on paperwork at a desk"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://californiainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim terms defined","item":"https://californiainsuranceappraiser.com/claim-terms-defined/"}],"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance claim terms defined","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expenses (ALE)","description":"Extra costs of living elsewhere while your home is repaired, such as rent and meals above normal.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal","description":"A policy process for resolving disputes over the amount of a covered loss using two appraisers and an umpire.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written, itemized decision signed by any two panel members that sets the amount of loss.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal demand","description":"A written request by either party to resolve an amount-of-loss dispute through appraisal.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Building code upgrade coverage","description":"Coverage for repair costs required by current building codes, often limited to a percentage of the dwelling limit.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"CDI","description":"The California Department of Insurance, the state agency that regulates insurers, led by the elected Insurance Commissioner.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"California Earthquake Authority (CEA)","description":"A publicly managed, privately funded provider of residential earthquake insurance sold through participating insurers.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"California FAIR Plan","description":"An insurer-funded association that offers basic fire coverage when private insurance isn’t available.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Causation","description":"What caused the damage. Generally treated as a coverage question rather than a valuation question.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"The dwelling limit on a homeowner policy.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage C","description":"The personal property, or contents, limit on a homeowner policy.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for removing damaged property, sometimes an added percentage of the dwelling limit.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page listing limits, deductibles, endorsements and the policy period.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss you pay before the policy pays.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, subtracted from replacement cost to find ACV.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Difference in conditions (DIC)","description":"A policy that covers perils the FAIR Plan excludes, such as water damage and theft.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser with no financial stake in the outcome and no disqualifying relationship with the parties.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Dwelling fire policy","description":"A basic policy often used for rentals, covering named perils and frequently paying ACV.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Extended replacement cost","description":"Added coverage above the dwelling limit, often 20% to 50%, when rebuilding costs more than the limit.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Fair Claims Settlement Practices Regulations","description":"California regulations setting standards and time frames for how insurers handle claims.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Fire following earthquake","description":"Fire caused by an earthquake, generally covered under the standard fire policy even though earthquake damage is excluded.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"The recoverable depreciation an insurer pays after repairs or replacement are complete.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"HO-3","description":"The most common homeowner policy form, covering the dwelling on an open-perils basis.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"HO-6","description":"A condominium unit-owner policy covering interiors, improvements and contents.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Insurance Code §2071","description":"The California statute containing the standard form fire policy, including its appraisal provision.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Like kind and quality","description":"Replacement with materials or items of similar type, grade and features.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate, such as a quantity of drywall or roofing, with its unit price.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"Whether repaired areas can reasonably match undamaged areas in color, texture and material.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Master policy","description":"The insurance policy an HOA carries on common areas and, often, the building structure.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping or drying.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charges for coordinating a job, often 10% plus 10% on multi-trade repairs.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of claim","description":"The documentation an insurer needs to evaluate a claim. California’s 40-day decision period runs from its receipt.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation you can collect after completing repairs under a replacement cost policy.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace with like kind and quality, without depreciation.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repairs needed to restore them.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"State of emergency","description":"A declaration by the Governor or President that can trigger added insurance protections in California.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy deadline to file a lawsuit against the insurer, subject to California tolling rules.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missing or under-priced in the original estimate.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third panel member who decides items the two appraisers cannot agree on.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Widely used estimating software for insurance repair estimates, with regional price lists.","inDefinedTermSet":{"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}}],"@id":"https://californiainsuranceappraiser.com/claim-terms-defined/#definedtermset"}]}</script>
</head>
